import { useState } from "react";
import { Button } from "../../components/ui/button";
import { useI18n } from "../../i18n/I18nProvider";

/** A passphrase generated by the server, shown once, to copy and hand over in person. */
export function GeneratedPassphrase({
  passphrase,
  handedOver,
  onHandedOverChange,
}: {
  passphrase: string;
  handedOver: boolean;
  onHandedOverChange(value: boolean): void;
}) {
  const { t } = useI18n();
  const [copied, setCopied] = useState(false);
  return (
    <div className="admin-passphrase" data-testid="passphrase-generated">
      <p className="admin-hint">{t("users.passphraseShownOnce")}</p>
      <div className="admin-passphrase-value">
        <code data-testid="passphrase-value">{passphrase}</code>
        <Button
          type="button"
          variant="secondary"
          data-testid="passphrase-copy"
          onClick={() =>
            void navigator.clipboard.writeText(passphrase).then(
              () => setCopied(true),
              () => setCopied(false),
            )
          }
        >
          {t(copied ? "users.passphraseCopied" : "users.passphraseCopy")}
        </Button>
      </div>
      <label className="checkbox-field">
        <input
          type="checkbox"
          data-testid="passphrase-handed-over"
          checked={handedOver}
          onChange={(event) => onHandedOverChange(event.currentTarget.checked)}
        />
        {t("users.passphraseHandedOver")}
      </label>
    </div>
  );
}
